{
  "name": "rf_channel_config_update",
  "confidence": "medium",
  "docstring": "Conditionally applies radio channel configuration to an interface context and emits an HCI channel-config event when the input status word indicates the expected channel update.",
  "subsystem": "rf",
  "var_renames": {
    "result": "status_word",
    "a2": "ctx_idx",
    "a3": "chcfg_idx",
    "v3": "chcfg_state",
    "v5": "status_bits",
    "v7": "ctx_state",
    "v16": "chan_count",
    "v31": "evt_buf",
    "v34": "chcfg_table_entry",
    "v35": "ctx_table_entry",
    "v36": "ctx_cfg_base"
  },
  "struct_hints": [
    {
      "offset": 106,
      "meaning": "channel configuration state byte; value 2 selects the active config path"
    },
    {
      "offset": 34,
      "meaning": "per-context selected channel/config index byte"
    },
    {
      "offset": 35,
      "meaning": "channel/config count or status byte; values up to 0x1f are considered valid"
    },
    {
      "offset": 36,
      "meaning": "busy/update-in-progress flag byte for this channel configuration"
    },
    {
      "offset": 664,
      "meaning": "start of per-context channel configuration state area"
    }
  ]
}
